</div></main><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>document.querySelectorAll('[data-confirm]').forEach(x=>x.addEventListener('click',e=>{if(!confirm(x.dataset.confirm))e.preventDefault()}));const kode=document.querySelector('input[name="kode"]');if(kode){kode.readOnly=true;kode.placeholder='Otomatis dibuat saat disimpan';if(!kode.value)kode.value='Otomatis dibuat';}const reader=document.querySelector('#reader');if(reader){const fallback=document.createElement('div');fallback.className='alert alert-info text-start mt-3';fallback.innerHTML='<b>Kamera live tidak tersedia?</b><br><small>Alamat jaringan HTTP diblokir browser untuk kamera live. Gunakan kamera HP untuk mengambil foto QR, lalu sistem akan membacanya.</small><label class="btn btn-outline-primary w-100 mt-2">Ambil Foto QR<input id="qr-photo-input" type="file" accept="image/*" capture="environment" hidden></label><div id="photo-qr-reader" class="small mt-2"></div>';reader.insertAdjacentElement('afterend',fallback);document.querySelector('#qr-photo-input').addEventListener('change',async ev=>{const file=ev.target.files[0],out=document.querySelector('#photo-qr-reader');if(!file)return;out.textContent='Membaca QR Code…';try{const scanner=new Html5Qrcode('photo-qr-reader');const decoded=await scanner.scanFile(file,true);if(typeof ok==='function')ok(decoded);else location.href=decoded;}catch(err){out.innerHTML='<span class="text-danger">QR tidak dapat dibaca. Ambil foto yang lebih jelas lalu coba lagi.</span>';}});}</script></body></html>
